// Parse the model's JSON response and attach our own review-routing logic.
// This node is also what LangSmith would wrap/trace in the real deployment
// (see langsmith/README.md) - it's the single point where we decide whether
// a human needs to look at this before it's saved.
const raw = $input.item.json;
let extracted;
try {
  const text = raw.content?.[0]?.text ?? raw.content;
  extracted = JSON.parse(text);
} catch (err) {
  return {
    json: {
      status: 'extraction_failed',
      reason: 'Model did not return parseable JSON',
      raw_response: raw
    }
  };
}

// Design decision, stated explicitly per the research pack's honesty
// commitment: AI Index 2026's MortgageTax benchmark shows even frontier
// models don't reliably exceed ~70% accuracy on this document category.
// We treat 0.70 as a hard ceiling for "trust without a second look", not
// just a routing threshold for obviously-bad extractions.
const CONFIDENCE_THRESHOLD = 0.70;
const needsReview = (extracted.confidence ?? 0) < CONFIDENCE_THRESHOLD;

return {
  json: {
    property_id: $('Validate Upload').item.json.property_id,
    uploaded_at: $('Validate Upload').item.json.uploaded_at,
    ...extracted,
    needs_human_review: needsReview,
    review_reason: needsReview
      ? `Confidence ${extracted.confidence} below ${CONFIDENCE_THRESHOLD} threshold`
      : null
  }
};

// Both branches still go back to the landlord for a confirm/edit step -
// this branch is just flagged as higher-priority / pre-filled with less
// confidence, per the workflow's human-in-the-loop design.
return {
  json: {
    ...$json,
    ui_state: 'pending_manual_review',
    ui_message: 'We could not confidently read this document. Please check the pre-filled fields below before saving.'
  }
};

return {
  json: {
    ...$json,
    ui_state: 'pending_quick_confirm',
    ui_message: 'We read this document with high confidence. Please glance over it and confirm.'
  }
};
